const text = $json.output;  // adjust to your field
// Option A: strip backslashes from escaped markdown
let cleaned = text.replace(/\\\\n/g, '\n')
                  .replace(/\\\\\*/g, '*');
// Option B: escape all underscores, asterisks, etc. for Markdown:
cleaned = cleaned.replace(/_/g, '\\_')
                 .replace(/\*/g, '\\*')
                 .replace(/\[/g, '\\[')
                 .replace(/`/g, '\\`');
return [{ text: cleaned }];
